################################################################################
## Form generated by hand to match the Designer-output pattern (no .ui file).
##
## PDF 排序 Tab 的纯布局代码 —— 与 excel_merge/invoice 的 generated/ui_*_dialog.py
## 风格一致:一个 Ui_* 类,setupUi(self, Widget) 构建控件树。
## 业务逻辑(信号连接/排序/结果展示)留在 dialogs/pdf_sort_tab.py 的 PdfSortTab。
##
## WARNING! 若日后用 Qt Designer 重新生成,本文件会被覆盖。
##
## 本文件在 scripts/regen_ui.py 的 HANDMADE 清单中(无 .ui、不走 pyside6-uic 再生)。
################################################################################

from PySide6.QtWidgets import (
    QComboBox,
    QHBoxLayout,
    QHeaderView,
    QLabel,
    QLineEdit,
    QListWidget,
    QPushButton,
    QTableWidget,
    QVBoxLayout,
    QWidget,
)

# 结果表格列头(与排序结果字段一一对应;放此处供 setupUi 与测试共用)
HEADERS = ["文件", "原页", "新页", "排序文字", "状态"]

# 选项下拉框文案(索引 -> 常量值的映射见 controllers/pdf_sort_controller.py)
ORDER_LABELS = ["升序(从小到大)", "降序(从大到小)"]
UNMATCHED_LABELS = ["排到最后", "排到最前", "报错不排序"]

# 匹配格式输入提示(示例与 CLI --pattern help 保持一致)
PATTERN_HINT = '正则表达式;首个捕获组作为排序文字,如 出库日期[:：]\\s*([0-9-]+)'


class Ui_PdfSortDialog:
    """PDF 排序 Tab 的 UI 构建器(setupUi 模式,与其他 Tab 一致)。"""

    def setupUi(self, PdfSortDialog: QWidget) -> None:
        if not PdfSortDialog.objectName():
            PdfSortDialog.setObjectName("PdfSortDialog")

        layout = QVBoxLayout(PdfSortDialog)
        layout.setObjectName("verticalLayout_main")

        # ---- 文件选择行 ----
        file_row = QHBoxLayout()
        file_row.setObjectName("horizontalLayout_files")

        self.btn_add_files = QPushButton("添加文件", PdfSortDialog)
        self.btn_add_files.setObjectName("btn_add_files")
        file_row.addWidget(self.btn_add_files)

        self.btn_add_folder = QPushButton("添加文件夹", PdfSortDialog)
        self.btn_add_folder.setObjectName("btn_add_folder")
        file_row.addWidget(self.btn_add_folder)

        self.btn_clear = QPushButton("清空", PdfSortDialog)
        self.btn_clear.setObjectName("btn_clear")
        file_row.addWidget(self.btn_clear)

        file_row.addStretch(1)
        layout.addLayout(file_row)

        self.list_files = QListWidget(PdfSortDialog)
        self.list_files.setObjectName("list_files")
        layout.addWidget(self.list_files)

        # ---- 匹配格式行 ----
        pattern_row = QHBoxLayout()
        pattern_row.setObjectName("horizontalLayout_pattern")

        pattern_row.addWidget(QLabel("匹配格式:", PdfSortDialog))

        self.edit_pattern = QLineEdit(PdfSortDialog)
        self.edit_pattern.setObjectName("edit_pattern")
        self.edit_pattern.setPlaceholderText(PATTERN_HINT)
        pattern_row.addWidget(self.edit_pattern)

        layout.addLayout(pattern_row)

        self.lbl_pattern_hint = QLabel(PATTERN_HINT, PdfSortDialog)
        self.lbl_pattern_hint.setObjectName("lbl_pattern_hint")
        layout.addWidget(self.lbl_pattern_hint)

        # ---- 选项行(方向 / 未匹配页) ----
        opt_row = QHBoxLayout()
        opt_row.setObjectName("horizontalLayout_options")

        opt_row.addWidget(QLabel("方向:", PdfSortDialog))

        self.cmb_order = QComboBox(PdfSortDialog)
        self.cmb_order.setObjectName("cmb_order")
        self.cmb_order.addItems(ORDER_LABELS)
        self.cmb_order.setCurrentIndex(0)
        opt_row.addWidget(self.cmb_order)

        opt_row.addWidget(QLabel("未匹配页:", PdfSortDialog))

        self.cmb_unmatched = QComboBox(PdfSortDialog)
        self.cmb_unmatched.setObjectName("cmb_unmatched")
        self.cmb_unmatched.addItems(UNMATCHED_LABELS)
        self.cmb_unmatched.setCurrentIndex(0)
        opt_row.addWidget(self.cmb_unmatched)

        opt_row.addStretch(1)
        layout.addLayout(opt_row)

        # ---- 输出目录行 ----
        out_row = QHBoxLayout()
        out_row.setObjectName("horizontalLayout_output")

        out_row.addWidget(QLabel("输出目录:", PdfSortDialog))

        self.edit_outdir = QLineEdit(PdfSortDialog)
        self.edit_outdir.setObjectName("edit_outdir")
        self.edit_outdir.setPlaceholderText("选择或输入输出目录(默认跟随上次或首个源文件目录)")
        out_row.addWidget(self.edit_outdir)

        self.btn_browse = QPushButton("浏览", PdfSortDialog)
        self.btn_browse.setObjectName("btn_browse")
        out_row.addWidget(self.btn_browse)

        layout.addLayout(out_row)

        # ---- 操作按钮行 ----
        btn_row = QHBoxLayout()
        btn_row.setObjectName("horizontalLayout_buttons")

        self.btn_sort = QPushButton("开始排序", PdfSortDialog)
        self.btn_sort.setObjectName("btn_sort")
        btn_row.addWidget(self.btn_sort)

        btn_row.addStretch(1)

        self.lbl_status = QLabel("就绪", PdfSortDialog)
        self.lbl_status.setObjectName("lbl_status")
        btn_row.addWidget(self.lbl_status)

        layout.addLayout(btn_row)

        # ---- 结果表格 ----
        self.table = QTableWidget(0, len(HEADERS), PdfSortDialog)
        self.table.setObjectName("table")
        self.table.setHorizontalHeaderLabels(HEADERS)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        layout.addWidget(self.table, stretch=1)
